import {Component, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';
import {RouterModule, ActivatedRoute} from '@angular/router';
import {FormsModule} from '@angular/forms';
import {ProductService} from '../product.service';
import {Product} from '../models/product.model';
import {CartService} from '../cart.service';

@Component({
    selector: 'app-product-detail',
    standalone: true,
    imports: [CommonModule, RouterModule, FormsModule],
    templateUrl: './product-detail.component.html',
    styleUrl: './product-detail.component.css'
})
export class ProductDetailComponent implements OnInit {

    product: any = {
        id: null, // Initialize with null or undefined
        name: 'Loading...',
        brand: '',
        price: 0,
        originalPrice: null, // Initialize with null or undefined
        description: 'Loading product details...',
        image: '', // Main image
        gallery: [], // For additional images
        category: 'Products',
        inStock: true,
        rating: 0, // Default rating
        reviewCount: 0, // Default review count
        features: [] // Extracted or provided features
    };
    selectedImage: string | null = null; // To manage selected image in gallery
    searchQuery: string = '';
    quantity: number = 1;
    isLoading: boolean = false;
    error: string | null = null;

    constructor(
        private route: ActivatedRoute,
        private productService: ProductService,
        private cartService: CartService
    ) {
    }

    ngOnInit(): void {
        // Get product ID from route parameters
        this.route.params.subscribe(params => {
            if (params['id']) {
                this.loadProduct(params['id']);
            } else {
                // Handle case where no ID is provided - try to get it from query params
                this.route.queryParams.subscribe(queryParams => {
                    if (queryParams['name']) {
                        this.loadProductByName(queryParams['name']);
                    }
                });
            }
        });
    }

    loadProduct(id: string): void {
        this.isLoading = true;
        this.productService.getProductById(Number(id)).subscribe({
            next: (product) => {
                if (product) {
                    this.processProduct(product);
                } else {
                    this.error = 'Product not found.'; // Handle product not found
                    console.error('Product not found for ID:', id);
                }
                this.isLoading = false;
            },
            error: (err) => {
                console.error('Error loading product details:', err);
                this.error = 'Unable to load product. Please try again later.';
                this.isLoading = false;
            }
        });
    }

    loadProductByName(name: string): void {
        this.isLoading = true;
        this.productService.getProductByName(name).subscribe({
            next: (product) => {
                if (product) {
                    this.processProduct(product);
                } else {
                    this.error = 'Product not found';
                }
                this.isLoading = false;
            },
            error: (err) => {
                console.error('Error loading product by name:', err);
                this.error = 'Unable to load product. Please try again later.';
                this.isLoading = false;
            }
        });
    }

    // Process the product data from API to match our UI needs
    processProduct(productData: Product): void {
        // Convert API product to UI format
        // Assuming productData is the raw product object from your service
        this.product = {
            id: productData.id || null, // Use actual ID if available
            name: productData.name,
            brand: productData.brandName,
            // Ensure price is a number, attempt to parse if it\'s a string
            price: typeof productData.price === 'string' ? parseFloat(productData.price.replace(/[^0-9.]/g, '')) : productData.price,
            // Assuming originalPrice might also come as a string or be absent
            originalPrice: productData.originalPrice ? (typeof productData.originalPrice === 'string' ? parseFloat(productData.originalPrice.replace(/[^0-9.]/g, '')) : productData.originalPrice) : null,
            description: productData.description,
            image: productData.imageLink, // Main image
            gallery: productData.gallery || (productData.imageLink ? [productData.imageLink] : []), // Use provided gallery or fallback to main image
            category: productData.category || 'Products', // Use actual category if available
            inStock: productData.inStock !== undefined ? productData.inStock : true, // Default to true if not specified
            rating: productData.rating || 0,
            reviewCount: productData.reviewCount || 0,
            features: this.extractFeatures(productData.description, productData.features) // Pass existing features if available
        };
        this.selectedImage = this.product.image; // Set the main image as selected initially
        this.isLoading = false;
    }

    // Updated Extract features from description and/or dedicated features array
    extractFeatures(description: string, existingFeatures?: string[]): string[] {
        if (existingFeatures && existingFeatures.length > 0) {
            return existingFeatures; // Prefer dedicated features if available
        }

        const features: string[] = [];
        // Example: Extract features based on keywords or structure in description
        // This is a placeholder. You\'ll need to adjust this logic based on your actual description format.

        // Attempt to parse Vietnamese-style key-value pairs if present
        const vietnameseKeyValues = [
            { key: "Trọng lượng", label: "Trọng lượng" },
            { key: "Chất liệu", label: "Chất liệu" },
            { key: "Kích thước", label: "Kích thước" },
            { key: "Thể tích", label: "Thể tích" },
            // Add more known keys if necessary
        ];

        vietnameseKeyValues.forEach(kv => {
            const regex = new RegExp(`${kv.key}:\\s*([^\\.\\n\\r]+)`, 'i');
            const match = regex.exec(description);
            if (match && match[1]) {
                features.push(`${kv.label}: ${match[1].trim()}`);
            }
        });

        // Fallback: if no specific features extracted, try to get some general lines
        if (features.length === 0) {
            const sentences = description.split(/[\\.\\!\\?]/)
                .map(s => s.trim())
                .filter(s => s.length > 10 && s.length < 150); // Filter for reasonable length sentences
            features.push(...sentences.slice(0, 3)); // Take up to 3 sentences
        }

        return features.length > 0 ? features : ['Xem chi tiết trong phần mô tả sản phẩm.'];
    }

    formatDescription(description: string): string[] {
        if (!description) return [];
        // Split by newlines, then filter out potential feature lines already handled by extractFeatures
        return description
            .split(/\r?\n+/)
            .map(line => line.trim())
            .filter(line => line.length > 0 && !/(Trọng lượng:|Chất liệu:|Kích thước:|Thể tích:)/i.test(line));
    }

    onAddToCart(): void {
        if (!this.product || this.product.id === null) {
            console.error('Product data is not fully loaded yet.');
            // Optionally, show a user notification
            return;
        }
        this.isLoading = true;
        const cartProduct: Product = {
            id: this.product.id, // Ensure ID is passed
            name: this.product.name,
            brandName: this.product.brand,
            price: this.product.price.toString(), // Cart service might expect string
            imageLink: this.product.image,
            detailLink: window.location.href, // Or a router link to the product
            description: this.product.description, // Optional: cart might not need full description
            quantity: this.quantity,
            // Ensure all required fields for Product model are present
            category: this.product.category,
            inStock: this.product.inStock,
            rating: this.product.rating,
            reviewCount: this.product.reviewCount,
            features: this.product.features,
            originalPrice: this.product.originalPrice ? this.product.originalPrice.toString() : undefined
        };

        this.cartService.addToCart(cartProduct);
        // Add a small delay to simulate processing and give feedback
        setTimeout(() => {
            this.isLoading = false;
            console.log('Added to cart:', cartProduct);
            // Optionally, navigate to cart or show a success message
        }, 500);
    }

    onAddToWishlist(): void {
        console.log('Adding to wishlist:', this.product);
    }

    onSearch(): void {
        if (this.searchQuery.trim()) {
            console.log('Searching for:', this.searchQuery);
        }
    }

    incrementQuantity(): void {
        this.quantity++;
    }

    decrementQuantity(): void {
        if (this.quantity > 1) {
            this.quantity--;
        }
    }

    onQuantityChange(): void {
        if (this.quantity < 1) {
            this.quantity = 1;
        }
    }

    getDiscountPercentage(): number {
        if (this.product.originalPrice && this.product.price) {
            return Math.round(((this.product.originalPrice - this.product.price) / this.product.originalPrice) * 100);
        }
        return 0;
    }
}
