<div class="py-6 px-4">
    <div class="container mx-auto">
        <!-- Breadcrumb -->
        <div class="flex flex-wrap gap-2 mb-6">
            <a class="text-[#99674d] hover:text-[#eb6c28] text-sm font-medium leading-normal transition-colors"
               routerLink="/home">Products</a>
            <span class="text-[#99674d] text-sm font-medium leading-normal">/</span>
            <span class="text-[#1b120e] text-sm font-medium leading-normal">{{ product.name }}</span>
        </div>

        <!-- Product Detail Section -->
        <div class="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">

            <!-- Product Image Carousel -->
            <div class="w-full">
                <div class="aspect-[4/3] rounded-xl overflow-hidden shadow-lg mb-4">
                    <img [src]="selectedImage || product.image" alt="{{ product.name }}" class="w-full h-full object-cover product-image">
                </div>
                <!-- Thumbnail images if available -->
                <div *ngIf="product.gallery && product.gallery.length > 0" class="flex gap-2 overflow-x-auto">
                    <img *ngFor="let img of product.gallery" [src]="img" alt="Thumbnail of {{ product.name }}"
                         class="w-20 h-20 object-cover rounded-md cursor-pointer border-2"
                         [class.border-[#eb6c28]]="selectedImage === img"
                         (click)="selectedImage = img">
                </div>
            </div>

            <!-- Product Information -->
            <div class="flex flex-col justify-start">
                <h1 class="text-[#1b120e] text-3xl lg:text-4xl font-bold leading-tight tracking-tight pb-2">
                    {{ product.name }}
                </h1>
                <p class="text-[#99674d] text-lg font-medium leading-normal pb-4">
                    By <a href="#" class="hover:text-[#eb6c28]">{{ product.brand }}</a>
                </p>

                <!-- Price and Rating -->
                <div class="flex items-center justify-between pb-4 border-b border-[#f3ebe7]">
                    <div>
                        <span class="text-[#1b120e] text-3xl font-bold leading-normal">{{ product.price | currency:'VND':'symbol':'1.0-0' }}</span>
                        <span *ngIf="product.originalPrice && product.originalPrice > product.price"
                              class="text-[#99674d] text-lg line-through ml-2">{{ product.originalPrice | currency:'VND':'symbol':'1.0-0' }}</span>
                    </div>
                    <div *ngIf="getDiscountPercentage() > 0"
                         class="bg-[#eb6c28] text-white px-3 py-1 rounded-full text-sm font-semibold">
                        {{ getDiscountPercentage() }}% OFF
                    </div>
                </div>
                <div class="flex items-center gap-2 py-4">
                    <div class="flex text-yellow-400">
                        <span *ngFor="let star of [1,2,3,4,5]"
                              [class]="star <= product.rating ? 'text-yellow-400' : 'text-gray-300'" class="text-xl">★</span>
                    </div>
                    <span class="text-[#99674d] text-sm">({{ product.reviewCount }} reviews)</span>
                </div>

                <!-- Key Features -->
                <div class="pb-6">
                    <h3 class="text-[#1b120e] text-lg font-semibold mb-3">Key Features:</h3>
                    <ul class="space-y-2 list-disc list-inside text-[#99674d]">
                        <li *ngFor="let feature of product.features" class="text-base leading-relaxed">
                            {{ feature }}
                        </li>
                    </ul>
                </div>

                <!-- Product Description -->
                <div class="pb-6">
                    <h3 class="text-[#1b120e] text-lg font-semibold mb-3">Description:</h3>
                    <ng-container *ngFor="let paragraph of formatDescription(product.description)">
                        <p class="text-[#99674d] text-base leading-relaxed pb-3">
                            {{ paragraph }}
                        </p>
                    </ng-container>
                </div>

                <!-- Quantity Selector -->
                <div class="pb-6">
                    <label class="block text-[#1b120e] text-lg font-semibold mb-2">Quantity:</label>
                    <div class="flex items-center gap-3">
                        <button class="w-10 h-10 rounded-lg border border-[#e0e3e6] flex items-center justify-center text-[#60758a] hover:bg-[#f0f2f5] transition-colors quantity-controls"
                                (click)="decrementQuantity()" [disabled]="quantity <= 1">
                            <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1z" clip-rule="evenodd"></path></svg>
                        </button>
                        <input type="number" [(ngModel)]="quantity" (change)="onQuantityChange()"
                               class="w-16 h-10 text-center border border-[#e0e3e6] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#eb6c28]/50 focus:border-[#eb6c28] text-[#1b120e] text-lg"
                               min="1">
                        <button class="w-10 h-10 rounded-lg border border-[#e0e3e6] flex items-center justify-center text-[#60758a] hover:bg-[#f0f2f5] transition-colors quantity-controls"
                                (click)="incrementQuantity()">
                            <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clip-rule="evenodd"></path></svg>
                        </button>
                    </div>
                </div>

                <!-- Action Buttons -->
                <div class="flex flex-col sm:flex-row gap-4 pt-4 border-t border-[#f3ebe7]">
                    <button class="flex-1 btn-primary flex items-center justify-center h-12 px-6 rounded-lg text-base font-semibold"
                            (click)="onAddToCart()" [disabled]="!product.inStock || isLoading"
                            [class.opacity-50]="!product.inStock || isLoading">
                        <svg class="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20"><path d="M3 1a1 1 0 000 2h1.22l.305 1.222a.997.997 0 00.01.042l1.358 5.43-.893.892C3.74 11.846 4.632 14 6.414 14H15a1 1 0 000-2H6.414l1-1H14a1 1 0 00.894-.553l3-6A1 1 0 0017 3H6.28l-.31-1.243A1 1 0 005 1H3zM16 16.5a1.5 1.5 0 11-3 0 1.5 1.5 0 013 0zM6.5 18a1.5 1.5 0 100-3 1.5 1.5 0 000 3z"></path></svg>
                        <span class="truncate">{{ isLoading ? 'Processing...' : (product.inStock ? 'Add to Cart' : 'Out of Stock') }}</span>
                    </button>
                    <button class="flex-1 btn-outline flex items-center justify-center h-12 px-6 rounded-lg text-base font-semibold"
                            (click)="onAddToWishlist()" [disabled]="isLoading">
                        <svg class="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M3.172 5.172a4 4 0 015.656 0L10 6.343l1.172-1.171a4 4 0 115.656 5.656L10 17.657l-6.828-6.829a4 4 0 010-5.656z" clip-rule="evenodd"></path></svg>
                        <span class="truncate">Add to Wishlist</span>
                    </button>
                </div>

                <!-- Stock Availability -->
                <div class="pt-4 text-sm">
                    <span *ngIf="product.inStock" class="text-green-600 font-semibold">In Stock</span>
                    <span *ngIf="!product.inStock" class="text-red-600 font-semibold">Out of Stock</span>
                </div>
            </div>
        </div>

        <!-- Additional Information Tabs (Optional) -->
        <!-- You can add tabs for reviews, specifications, etc. here -->

        <!-- Related Products (Optional) -->
        <!-- You can add a related products section here -->

    </div>
</div>
